    'RegisterSimpleRisk'=>'Registrieren SimpleRisk',
    'RegistrationText'=>'Registrierten SimpleRisk-Instanzen wird sofort Zugriff auf die Upgrade- und Secure Controls Framework (SCF)-Extras gewährt. Das Upgrade-Extra bietet die Möglichkeit, Ihre SimpleRisk-Instanz mit einem Klick auf eine Schaltfläche zu sichern und zu aktualisieren. Das Secure Controls Framework (SCF) Extra bietet ein gemeinsames Kontroll-Framework, das in die SimpleRisk-Governance-Funktionalität integriert ist. Bei der Registrierung von SimpleRisk werden Ihre Registrierungsinformationen an einen von SimpleRisk gehosteten Server gesendet. Die bereitgestellten Registrierungsinformationen werden von SimpleRisk verwendet, um Kunden über neue Versionen und Sicherheitsupdates zu informieren. Durch die Registrierung von SimpleRisk werden Sie für unsere Marketingmitteilungen angemeldet, Sie können sich jedoch jederzeit über den Link zum Abbestellen in diesen Mitteilungen abmelden. SimpleRisk respektiert die Privatsphäre unserer Kunden und Informationen, die uns durch den SimpleRisk-Registrierungsprozess bereitgestellt werden, werden niemals an Dritte verkauft.',
