    'UnlockActivateScfNote' => 'Das Secure Controls Framework wurde heruntergeladen, aber nicht aktiviert.',
    'UnlockActivateScfLink' => 'Schalte es ein',
    // Import-Export is a paid Extra, so "not installed" is an upsell rather
